@startuml

class SensorController {
}

class Apartment {
  + address : string
  + emailAddress : string
}

class Inhabitant {
  + username : string
  + password : string
  + isAdmin : boolean
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor extends Sensor {
  + min : float
  + max : float
}

class PowerSensor extends Sensor {
  + counterReading : float
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {}

SensorController "1" -- "*" Apartment : manages
Apartment "1" -- "1..*" Inhabitant : has
Apartment "1" -- "1" SensorController : contains
Apartment "1" -- "2..*" Room : consists of
Room "1" -- "1" Sensor : contains
Sensor "1" -- "*" MeasuredValue : records
SensorController "1" -- "1" EMonitor : monitored by
EMonitor "1" -- "*" Sensor : checks thresholds

@enduml

